def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Normalize fields to a dict mapping field names to types (or None)
    if isinstance(fields, (list, tuple)):
        fields = {f: None for f in fields}
    elif not isinstance(fields, dict):
        raise TypeError("fields must be a dict or list of field names")

    # Prepare class attributes and annotations
    attrs = {}
    annotations = {}
    for field, ftype in fields.items():
        annotations[field] = ftype if ftype is not None else object
        attrs[field] = None
    attrs['__annotations__'] = annotations

    # __init__ that accepts coordinates and optional field values
    def __init__(self, x, y, **kwargs):
        super(self.__class__, self).__init__(x, y)
        for key, value in kwargs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                raise AttributeError(f"Unknown field {key}")
    attrs['__init__'] = __init__

    # __repr__ that shows coordinates and field values
    def __repr__(self):
        field_parts = [f"{k}={getattr(self, k)!r}" for k in fields]
        return f"{name}({self.x}, {self.y}, " + ", ".join(field_parts) + ")"
    attrs['__repr__'] = __repr__

    # Add srid attribute if present in srid_map
    srid = srid_map.get(name)
    if srid is not None:
        attrs['srid'] = srid

    # Create and return the new subclass of Point
    return type(name, (Point,), attrs)

def deprecated(message):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(f"{func.__name__} is deprecated: {message}", DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorating_function(user_function):
        cache = {}
        counts = {}
        freq = {}
        from collections import OrderedDict

        def wrapper(*args, **kwargs):
            if typed:
                key = args + tuple((k, type(v)) for k, v in kwargs.items())
            else:
                key = args + tuple(sorted(kwargs.items()))
            if key in cache:
                old_count = counts[key]
                freq[old_count].pop(key)
                if not freq[old_count]:
                    del freq[old_count]
                new_count = old_count + 1
                counts[key] = new_count
                freq.setdefault(new_count, OrderedDict())[key] = None
                return cache[key]
            result = user_function(*args, **kwargs)
            if len(cache) >= maxsize:
                min_count = min(freq)
                evict_key, _ = freq[min_count].popitem(last=False)
                if not freq[min_count]:
                    del freq[min_count]
                del cache[evict_key]
                del counts[evict_key]
            cache[key] = result
            counts[key] = 1
            freq.setdefault(1, OrderedDict())[key] = None
            return result

        return wrapper

    return decorating_function

