def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    # Determine the minimal set of classes (no class is a subclass of another)
    minimal_set = set()
    for c in classes:
        # Skip if c is a subclass of any other class in the list
        if any(c != d and issubclass(c, d) for d in classes):
            continue
        minimal_set.add(c)
    # Preserve the original order of the minimal set
    seen = set()
    result = []
    for c in classes:
        if c in minimal_set and c not in seen:
            result.append(c)
            seen.add(c)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    seen = set()
    result = []
    classes = [self.__class__]
    if all:
        classes = self.__class__.__mro__
    for cls in classes:
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if name in seen:
                continue
            seen.add(name)
            desc = None
            if callable(value):
                desc = value.__doc__
            else:
                if isinstance(value, property):
                    desc = value.__doc__
                else:
                    desc = getattr(value, "__doc__", None)
            result.append((name, desc))
    return result

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Determine interface attribute names
    interface_attrs = set()
    if hasattr(self, '_attributes'):
        interface_attrs = set(self._attributes.keys())
    elif hasattr(self, '_interface'):
        interface_attrs = set(self._interface.keys())
    elif hasattr(self, '__annotations__'):
        interface_attrs = set(self.__annotations__.keys())
    else:
        # fallback: use dir and filter out callables and private attributes
        interface_attrs = {name for name in dir(self)
                           if not name.startswith('_')
                           and not callable(getattr(self, name))}
    if all:
        # Return all attribute names (including those not defined by interface)
        return list(self.__dict__.keys())
    return list(interface_attrs)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        # Expand nested sequences (lists or tuples) recursively
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, output)
        else:
            # Treat any non-iterable as an individual interface or implements spec
            output.append(item)
    return output

