def to_csv(self, separator=",", header=None):
        """
        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.
        """
        lines = []
        for point in getattr(self, "points", []):
            # Unpack coordinate and value; support both (coord, val) tuples
            # and single values where coordinate is implicit.
            if isinstance(point, tuple) and len(point) == 2:
                coord, val = point
            else:
                coord, val = point, None

            # Convert coordinate to string parts
            if isinstance(coord, (str, bytes)):
                coord_parts = [str(coord)]
            elif hasattr(coord, "__iter__"):
                coord_parts = [str(c) for c in coord]
            else:
                coord_parts = [str(coord)]

            # Convert value to string parts
            if val is None:
                val_parts = []
            elif isinstance(val, (str, bytes)):
                val_parts = [str(val)]
            elif hasattr(val, "__iter__"):
                val_parts = [str(v) for v in val]
            else:
                val_parts = [str(val)]

            line = separator.join(coord_parts + val_parts)
            lines.append(line)

        csv = "\n".join(lines)
        if header is not None:
            csv = f"{header}\n{csv}"
        return csv

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # If error indices are stored in a dictionary mapping coordinate names to indices
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, dict):
        if coord_name in self._err_indices:
            val = self._err_indices[coord_name]
            return val if isinstance(val, (list, tuple)) else [val]
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")
    # If error indices are stored in a list/tuple aligned with coordinate names
    if hasattr(self, "_err_indices") and isinstance(self._err_indices, (list, tuple)):
        if hasattr(self, "_coord_names") and coord_name in self._coord_names:
            idx = self._coord_names.index(coord_name)
            val = self._err_indices[idx]
            return val if isinstance(val, (list, tuple)) else [val]
        raise KeyError(f"Coordinate '{coord_name}' not found in coordinate names.")
    # Fallback: compute error index assuming errors follow coordinates in order
    if hasattr(self, "_coord_names") and coord_name in self._coord_names:
        idx = self._coord_names.index(coord_name)
        return [idx + len(self._coord_names)]
    raise AttributeError("Coordinate name or error indices not defined.")

def _update_context(self, context):
    # Ensure the context has an error dictionary
    if hasattr(context, "error"):
        err_dict = context.error
    else:
        err_dict = context.get("error", {})
    # Retrieve the graph's fields (assumed to be a list of field names)
    fields = getattr(self, "fields", [])
    # Map the first three coordinate names to x, y, z
    coord_map = {}
    for i, name in enumerate(fields[:3]):
        coord_map[name] = ["x", "y", "z"][i]
    # Iterate over all fields to find error fields
    for idx, field in enumerate(fields):
        if field.startswith("error_"):
            # Extract the part after "error_"
            rest = field[len("error_") :]
            # Split into coordinate name and suffix
            parts = rest.split("_", 1)
            if len(parts) == 2:
                coord_name, suffix = parts
                if coord_name in coord_map:
                    # Build the error name using x, y, or z
                    error_name = f"{coord_map[coord_name]}_{suffix}"
                    # Append the index of this error field
                    err_dict[error_name] = {"index": idx}
    # Write the updated error dictionary back to the context
    if hasattr(context, "error"):
        context.error = err_dict
    else:
        context["error"] = err_dict

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not bins:
        return 0.0
    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")
    widths = [edges[i + 1] - edges[i] for i in range(len(bins))]
    return sum(b * w for b, w in zip(bins, widths))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude a Source instance
    try:
        if isinstance(seq, Source):
            return False
    except NameError:
        pass

    # Direct FillRequest instance
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        pass

    # Try to iterate over seq
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Check for at least one FillRequest element
    for item in iterator:
        try:
            if isinstance(item, FillRequest):
                return True
        except NameError:
            continue

    return False

