def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # key only in d1
            result[key] = val1
        else:
            val2 = d2[key]
            # both values are dicts
            if isinstance(val1, dict) and isinstance(val2, dict):
                # decide whether to recurse
                if level == 0:
                    # no recursion: treat as values
                    if val1 != val2:
                        result[key] = val1
                else:
                    # recurse with decremented level if positive
                    sublevel = level - 1 if level > 0 else -1
                    subdiff = difference(val1, val2, sublevel)
                    if subdiff:
                        result[key] = subdiff
            else:
                # at least one value is not a dict
                if val1 != val2:
                    result[key] = val1
    return result

def _validate_labels(labels):
    import re
    key_regex = re.compile(r'^([A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?\/)?[A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?$')
    value_regex = re.compile(r'^([A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?)?$')
    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): 'expected string or bytes-like object'})
        else:
            if not key_regex.fullmatch(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value(s)
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({repr(v): 'expected string or bytes-like object'})
                else:
                    if not value_regex.fullmatch(v):
                        errors.append({v: f"Label value '{v}' does not match the regex [...]"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({repr(value): 'expected string or bytes-like object'})
            else:
                if not value_regex.fullmatch(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        raise ValidationError(errors)

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os

    if not os.path.exists(path):
        return False

    # If path is a directory, determine if it's an OCFL root or an object
    if os.path.isdir(path):
        # Check for OCFL root structure
        root_obj_dir = os.path.join(path, 'objects')
        ocfl_meta = os.path.join(path, 'ocfl.json')
        if os.path.isdir(root_obj_dir) and os.path.isfile(ocfl_meta):
            # Validate each object in the root
            for obj_name in os.listdir(root_obj_dir):
                obj_path = os.path.join(root_obj_dir, obj_name)
                if not self._validate_object(obj_path):
                    return False
            return True
        else:
            # Treat as a single object
            return self._validate_object(path)

    # If path is a file, cannot be a valid OCFL object
    return False

