def validate(self, inventory, extract_spec_version=False):
    # Inventory must be a dictionary
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine the specification version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Attempt to extract a version number from the type string
            # e.g., "inventory_v2" -> 2
            parts = type_val.split("_")
            if parts and parts[-1].startswith("v"):
                try:
                    spec_version = int(parts[-1][1:])
                except ValueError:
                    # Fall back to the class's spec_version if parsing fails
                    spec_version = self.spec_version

    # Ensure the inventory has a spec_version key that matches the determined version
    inv_spec = inventory.get("spec_version")
    if inv_spec is None:
        # If missing, add it
        inventory["spec_version"] = spec_version
    else:
        # Compare after normalizing to int
        try:
            inv_spec_int = int(inv_spec)
        except (TypeError, ValueError):
            raise ValueError("Inventory 'spec_version' must be an integer or string representing an integer")
        if inv_spec_int != spec_version:
            raise ValueError(f"Inventory spec_version {inv_spec_int} does not match expected {spec_version}")

    # Basic required keys for a valid inventory
    required_keys = ["type", "spec_version", "items"]
    for key in required_keys:
        if key not in inventory:
            raise ValueError(f"Missing required key '{key}' in inventory")

    # Validate that 'items' is a list
    items = inventory["items"]
    if not isinstance(items, list):
        raise ValueError("Inventory 'items' must be a list")

    # Validate each item in the list
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise ValueError(f"Item at index {idx} is not a dictionary")
        # Example required fields for an item
        if "name" not in item or "quantity" not in item:
            raise ValueError(f"Item at index {idx} missing required 'name' or 'quantity' fields")

    # If all checks pass, return the (possibly updated) inventory
    return inventory

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # If the requested version is not present, return an empty mapping.
    if version not in inventory:
        return {}

    # Start with the logical paths and files from the requested version.
    result = {}
    state = inventory[version]
    for logical_path, content_file in state.items():
        result[logical_path] = {content_file}

    # Include any duplicate files that appear in later versions.
    for v, later_state in inventory.items():
        if v <= version:
            continue
        for logical_path, content_file in later_state.items():
            if logical_path in result:
                result[logical_path].add(content_file)

    return result

