def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Python 3.8+
        from importlib import metadata
    except ImportError:
        try:
            # Older Python versions
            import importlib_metadata as metadata
        except ImportError:
            return "0.0.0"
    # Determine the distribution name from the current module's package
    pkg_name = __package__ or __name__
    if pkg_name:
        pkg_name = pkg_name.split('.')[0]
    else:
        return "0.0.0"
    try:
        return metadata.version(pkg_name)
    except Exception:
        return "0.0.0"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Extract pieces
    if pieces is None:
        return ''
    if isinstance(pieces, dict):
        major = pieces.get('major')
        minor = pieces.get('minor')
        patch = pieces.get('patch')
        pre = pieces.get('pre_release')
        build = pieces.get('build')
    else:
        # Assume list/tuple: [major, minor, patch, pre_release, build]
        major = pieces[0] if len(pieces) > 0 else None
        minor = pieces[1] if len(pieces) > 1 else None
        patch = pieces[2] if len(pieces) > 2 else None
        pre = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None

    # Build the base version string
    parts = []
    if major is not None:
        parts.append(str(major))
    if minor is not None:
        parts.append(str(minor))
    if patch is not None:
        parts.append(str(patch))
    base = '.'.join(parts)

    # Pre-release handling
    if pre:
        if style == 'semver':
            base += '-' + str(pre)
        elif style == 'pep440':
            base += '.dev' + str(pre)
        elif style == 'git':
            base += '-' + str(pre)
        else:
            base += '-' + str(pre)

    # Build metadata handling
    if build:
        if style == 'semver':
            base += '+' + str(build)
        elif style == 'pep440':
            base += '+post' + str(build)
        elif style == 'git':
            base += '+' + str(build)
        else:
            base += '+' + str(build)

    # Git style prefix
    if style == 'git':
        base = 'v' + base

    return base

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    return '.' if '+' in pieces else '+'

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    # Attach the VCS name to the function
    method._vcs_handler = vcs
    # Store in a registry for later lookup
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    register_vcs_handler._registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Attempt to get a traversal of the hierarchy.  If the object does not
    # provide a `traverse` method, fall back to treating the root itself as
    # a single object.
    if hasattr(self, "_root") and hasattr(self._root, "traverse"):
        iterator = self._root.traverse()
    else:
        iterator = [self] if hasattr(self, "is_object") else []

    for obj in iterator:
        num_objects += 1
        is_valid = True

        # Object-level validation
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    obj.validate()
                elif hasattr(obj, "is_valid"):
                    if not getattr(obj, "is_valid"):
                        is_valid = False
                # If no validation method/property is available, assume valid
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Validation failed for {obj!r}: {exc}")

        # Digest check
        if check_digests:
            try:
                if hasattr(obj, "compute_digest") and hasattr(obj, "digest"):
                    computed = obj.compute_digest()
                    if computed != obj.digest:
                        is_valid = False
                        if show_warnings:
                            print(f"[WARN] Digest mismatch for {obj!r}: expected {obj.digest!r}, got {computed!r}")
                # If no digest methods/properties, skip check
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARN] Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

