    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids:
        # Normalize bug_ids to a list of ints
        if isinstance(bug_ids, str):
            bug_ids = [int(x) for x in bug_ids.split(',') if x]
        elif not isinstance(bug_ids, list):
            bug_ids = [bug_ids]
        # Merge with existing 'ids' if present
        if 'ids' in params:
            existing = params['ids']
            if isinstance(existing, str):
                existing = [int(x) for x in existing.split(',') if x]
            elif not isinstance(existing, list):
                existing = [existing]
            # Combine and deduplicate while preserving order
            combined = []
            for id_ in existing + bug_ids:
                if id_ not in combined:
                    combined.append(id_)
            params['ids'] = combined
        else:
            params['ids'] = bug_ids
    return params

