def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value_node) tuples by key, deep merging MappingNode values.
    """
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged:
            merged[key] = (key_node, value_node)
        else:
            existing_key_node, existing_value_node = merged[key]
            # If both values are MappingNode, deep merge them
            if isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                # Merge the mapping node values recursively
                merged_pairs = deep_merge_nodes(existing_value_node.value + value_node.value)
                merged_node = ruamel.yaml.nodes.MappingNode(
                    tag=existing_value_node.tag,
                    value=merged_pairs
                )
                merged[key] = (existing_key_node, merged_node)
            else:
                # For non-mapping or one non-mapping, last value wins
                merged[key] = (existing_key_node, value_node)
    return [(k, v) for k, (_, v) in merged.items()]

