def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("size string is empty")

    # Try to parse numeric part and optional unit
    import re
    m = re.match(r'^([0-9]*\.?[0-9]+)\s*([kKmMgGtTpPeE]?)b?$', size)
    if m:
        num_str, unit = m.groups()
        num = float(num_str)
        unit = unit.upper()
        factor = 1
        if unit == 'K':
            factor = 1000
        elif unit == 'M':
            factor = 1000**2
        elif unit == 'G':
            factor = 1000**3
        elif unit == 'T':
            factor = 1000**4
        elif unit == 'P':
            factor = 1000**5
        elif unit == 'E':
            factor = 1000**6
        return int(round(num * factor))
    else:
        # If no unit, try to interpret as integer
        if size.isdigit():
            return int(size)
        else:
            raise ValueError(f"Invalid size format: {size}")

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

