def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._data:
        raise KeyError('popitem(): dictionary is empty')
    # Find the key with the lowest frequency
    min_freq = min(self._freq.values())
    # Pick any key that has this frequency
    for key, freq in self._freq.items():
        if freq == min_freq:
            break
    value = self._data.pop(key)
    self._freq.pop(key)
    # If the class keeps a bucket of keys per frequency, remove it from there
    if hasattr(self, '_freq_buckets'):
        bucket = self._freq_buckets.get(min_freq)
        if bucket:
            bucket.pop(key, None)
            if not bucket:
                del self._freq_buckets[min_freq]
    # Update the minimum frequency if needed
    if self._freq:
        self._minfreq = min(self._freq.values())
    else:
        self._minfreq = None
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self.cache:
