def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check public message
    try:
        public = getattr(request, 'public_message', None)
        if public:
            if isinstance(public, dict):
                if public.get('type') == 'diaspora' or 'diaspora' in public:
                    return True
            if isinstance(public, str) and 'diaspora' in public.lower():
                return True
    except Exception:
        pass

    # Check private message
    try:
        private = getattr(request, 'private_message', None)
        if private:
            if isinstance(private, dict):
                if private.get('type') == 'diaspora' or 'diaspora' in private:
                    return True
            if isinstance(private, str) and 'diaspora' in private.lower():
                return True
    except Exception:
        pass

    # Check legacy payload
    try:
        legacy = getattr(request, 'legacy_payload', None)
        if legacy:
            if isinstance(legacy, dict):
                if legacy.get('type') == 'diaspora' or 'diaspora' in legacy:
                    return True
            if isinstance(legacy, str) and 'diaspora' in legacy.lower():
                return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    # Attempt to get the request path
    path = None
    if hasattr(request, "path"):
        path = getattr(request, "path")
    elif hasattr(request, "url"):
        path = getattr(request, "url")
    elif isinstance(request, dict):
        path = request.get("path") or request.get("url")

    # If we have a path, check for the Matrix API prefix
    if isinstance(path, str) and path.startswith("/_matrix"):
        return True

    # Fallback: inspect headers for Matrix‑specific clues
    headers = None
    if hasattr(request, "headers"):
        headers = getattr(request, "headers")
    elif isinstance(request, dict):
        headers = request.get("headers")

    if isinstance(headers, dict):
        # Matrix requests sometimes include a custom header
        if headers.get("X-Matrix-Request") is not None:
            return True
        # Common content type for Matrix API
        content_type = headers.get("Content-Type", "")
        if content_type.startswith("application/json"):
            # If the path contains the word "matrix", it's likely a Matrix request
            if isinstance(path, str) and "matrix" in path.lower():
                return True

    # If none of the heuristics matched, assume it's not a Matrix request
    return False

