def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default path for the NodeInfo document
    if document_path is None:
        document_path = "/.well-known/nodeinfo/2.0"

    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Build the full href, stripping any trailing slash from the base URL
    href = url.rstrip("/") + document_path

    # Construct the .well-known document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from lxml import etree
        import xmlsec
    except ImportError:
        raise RuntimeError("lxml and xmlsec libraries are required for signature verification")

    # Parse the XML document
    try:
        root = etree.fromstring(doc if isinstance(doc, bytes) else doc.encode('utf-8'))
    except Exception as e:
        raise ValueError(f"Invalid XML document: {e}")

    # Find the Signature node
    sig_node = xmlsec.tree.find_node(root, xmlsec.constants.NodeSignature)
    if sig_node is None:
        raise ValueError("No Signature element found in the XML document")

    # Create a signature context
    ctx = xmlsec.SignatureContext()

    # Load the public key
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.constants.KeyDataFormatPem, None)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {e}")

    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(sig_node)
    except xmlsec.VerificationError:
        return False
    except Exception as e:
        raise RuntimeError(f"Signature verification failed: {e}")

    # Optionally, compare the provided signature string with the one in the XML
    # (if the signature argument is expected to be the base64-encoded signature)
    if signature:
        # Extract the signature value from the XML
        sig_value_elem = sig_node.find('.//{http://www.w3.org/2000/09/xmldsig#}SignatureValue')
        if sig_value_elem is None:
            raise ValueError("SignatureValue element not found in the XML")
        xml_sig_value = sig_value_elem.text.strip()
        if xml_sig_value != signature.strip():
            return False

    return True

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        data = json.loads(document)
        # Ensure the result is a dict
        if isinstance(data, dict):
            return data
    except Exception:
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except Exception as e:
        raise ValueError(f"Unable to parse webfinger document: {e}")

    # Namespace handling
    ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

    # Subject
    subject_elem = root.find('xrd:Subject', ns)
    subject = subject_elem.text if subject_elem is not None else None

    # Aliases
    aliases = [a.text for a in root.findall('xrd:Alias', ns) if a.text]

    # Links
    links = []
    for link in root.findall('xrd:Link', ns):
        link_dict = {}
        for attr in ['rel', 'type', 'href', 'templated']:
            if attr in link.attrib:
                link_dict[attr] = link.attrib[attr]
        # Include any nested elements inside <Link> as properties if needed
        for child in link:
            tag = child.tag
            if tag.startswith('{'):
                # strip namespace
                tag = tag.split('}', 1)[1]
            if child.text:
                link_dict[tag] = child.text
        links.append(link_dict)

    # Properties (top-level)
    properties = {}
    for prop in root.findall('xrd:Property', ns):
        name = prop.attrib.get('name')
        if name:
            properties[name] = prop.text

    result = {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }
    if properties:
        result['properties'] = properties

    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not handle or '@' not in handle:
        raise ValueError("Handle must be in the form local@domain")
    # Remove acct: prefix if present
    if handle.startswith('acct:'):
        handle = handle[5:]
    local, domain = handle.split('@', 1)
    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    try:
        resp = requests.get(url, timeout=10, headers={'Accept': 'application/jrd+json, application/json'})
        resp.raise_for_status()
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve webfinger for {handle}: {e}") from e
    try:
        data = resp.json()
    except Exception as e:
        raise ValueError(f"Failed to parse JSON from webfinger response for {handle}: {e}") from e
    return data

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    import os
    import fnmatch

    # Normalize settings_dirs to a list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    file_list = []

    for d in dirs:
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for f in files:
                # Apply spec_option filter if provided
                if spec_option is not None:
                    if isinstance(spec_option, str):
                        # Treat as glob pattern
                        if not fnmatch.fnmatch(f, spec_option):
                            continue
                    elif callable(spec_option):
                        # Treat as a predicate function
                        if not spec_option(f):
                            continue
                    else:
                        # Unsupported spec_option type; skip filtering
                        pass
                file_list.append(os.path.join(root, f))

    return file_list

