        spec_dict = spec_content
    else:
        raise IRValidatorException("Spec content must be a string or dict")
    if spec_dict is None:
        raise IRValidatorException("YAML content could not be parsed into a dictionary")
    required = getattr(cls, 'REQUIRED_FIELDS', [])
    missing = [field for field in required if field not in spec_dict]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return spec_dict

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("No YAML file provided")
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except Exception as e:
        raise IRValidatorException(f"Error loading YAML file: {e}")
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file does not contain a dictionary")
    required = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Import os locally to avoid requiring it at module level
    import os
    # Retrieve the spec object; if it doesn't exist, return empty defaults
    spec = getattr(self, "spec", None)
    if not spec:
        return defaults
    # Iterate over arguments defined in the spec
    for arg in getattr(spec, "args", []):
        # Start with the default defined in the spec, if any
        value = getattr(arg, "default", None)
        # If the argument has a 'value' attribute, prefer that over 'default'
        if hasattr(arg, "value"):
            value = getattr(arg, "value")
        # Override with environment variable if present (uppercase name)
        env_key = getattr(arg, "name", None)
        if env_key:
            env_val = os.getenv(env_key.upper())
            if env_val is not None:
                value = env_val
        # Override with configuration value if the instance has a config dict
        if hasattr(self, "config") and isinstance(self.config, dict):
            cfg_val = self.config.get(env_key)
            if cfg_val is not None:
                value = cfg_val
        # Store the resolved value
        if env_key:
            defaults[env_key] = value
    return defaults

def get_deprecated_args(self):
    """Return a dictionary mapping deprecated option names to their replacements."""
    # Example mapping of deprecated arguments to the new ones.
    # Update this dictionary as new deprecations are introduced.
    return {
        'old_option': 'new_option',
        'legacy_flag': 'modern_flag',
        'deprecated_mode': 'mode',
    }

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Find the subparsers action in the main parser
    subparsers_action = None
    for action in getattr(self, "parser", None)._actions:
        if action.__class__.__name__ == "_SubParsersAction":
            subparsers_action = action
            break

    if not subparsers_action:
        return []

    # Get the subparser for the requested command
    subparser = subparsers_action.choices.get(command_name)
    if not subparser:
        return []

    # Collect all option strings from the subparser's actions
    options = []
    for action in subparser._actions:
        if getattr(action, "option_strings", None):
            options.extend(action.option_strings)

    return options

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command's option specifications dictionary
    command_options = getattr(self, "_options", {})
    # Attempt to fetch the specific option spec
    try:
        return command_options[command_name][argument_name]
    except KeyError:
        # Provide a clear error message if the spec is missing
        raise KeyError(f"Option spec for command '{command_name}' and argument '{argument_name}' not found")

def get_silent_args(self, args):
    """
    Return a list of argument names that are considered silent.
    An argument is considered silent if its value is None or an empty string.
    The input `args` can be a dict, a namespace-like object, or an iterable of (name, value) pairs.
    """
    silent = []
    if isinstance(args, dict):
        for name, value in args.items():
            if value is None or value == '':
                silent.append(name)
    elif hasattr(args, '__dict__'):
        for name, value in vars(args).items():
            if value is None or value == '':
                silent.append(name)
    else:
        try:
            for name, value in args:
                if value is None or value == '':
                    silent.append(name)
        except Exception:
            pass
    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if args is None:
        args = {}
    required = getattr(self, 'required_args', [])
    missing = [arg for arg in required if arg not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = []
        for opt in options_spec:
            cond = opt.get('required_when')
            if cond is None:
                continue
            try:
                # If the condition is a callable, call it with the args dict
                if callable(cond):
                    if cond(args):
                        required.append(opt['name'])
                else:
                    # Treat the condition as a Python expression string.
                    # Provide a minimal context: the args dict and command_name.
                    context = {'args': args, 'command_name': command_name}
                    if eval(cond, {}, context):
                        required.append(opt['name'])
            except Exception:
                # If evaluation fails, ignore this option for requiredness.
                pass
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified."""
    # Determine max lengths mapping, if any
    max_lengths = getattr(self, 'max_lengths', {})
    for arg, value in args.items():
        # Get max length for this argument
        max_len = max_lengths.get(arg)
        if max_len is None:
            # Try attribute naming convention
            max_len = getattr(self, f"max_length_{arg}", None)
        if max_len is None:
            # No length constraint defined for this argument
            continue
        if value is None:
            # None values are considered acceptable
            continue
        try:
            length = len(value)
        except Exception:
            # If value has no length, skip validation
            continue
        if length > max_len:
            raise ValueError(f"Argument '{arg}' length {length} exceeds maximum allowed {max_len}.")

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Determine the mapping of argument names to values
        if isinstance(args, dict):
            arg_map = args
        else:
            # Assume argparse.Namespace or similar
            arg_map = vars(args)

        # Iterate over each argument that has defined choices
        for name, value in arg_map.items():
            if not hasattr(self, "_choices") or name not in self._choices:
                continue

            allowed = self._choices[name]
            # Normalize allowed to a set for efficient lookup
            if not isinstance(allowed, (set, list, tuple)):
                allowed = {allowed}
            else:
                allowed = set(allowed)

            # Skip validation if value is None
            if value is None:
                continue

            # If the value is a collection, validate each element
            if isinstance(value, (list, tuple, set)):
                for elem in value:
                    if elem not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{name}': {elem}. "
                            f"Allowed choices are: {sorted(allowed)}."
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value}. "
                        f"Allowed choices are: {sorted(allowed)}."
                    )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine iterable of values
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args
    # Validate each value
    for val in values:
        if not (self.min <= val <= self.max):
            raise ValueError(f"Argument value {val} out of bounds [{self.min}, {self.max}]")
    return True

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        All values are initially strings. This method attempts to convert
        them to bool, int, float, or list of strings where appropriate.
        """
        def _convert_value(val):
            # If already a list, convert each element
            if isinstance(val, list):
                return [_convert_value(v) for v in val]
            # If already a dict, recurse
            if isinstance(val, dict):
                return {k: _convert_value(v) for k, v in val.items()}
            # Only process strings
            if not isinstance(val, str):
                return val
            s = val.strip()
            # Boolean
            low = s.lower()
            if low == 'true':
                return True
            if low == 'false':
                return False
            # Integer
            if s.isdigit() or (s.startswith('-') and s[1:].isdigit()):
                try:
                    return int(s)
                except ValueError:
                    pass
            # Float
            try:
                f = float(s)
                # Ensure it's not an int disguised as float
                if '.' in s or 'e' in s.lower():
                    return f
            except ValueError:
                pass
            # List (comma separated)
            if ',' in s:
                parts = [p.strip() for p in s.split(',')]
                return [_convert_value(p) for p in parts]
            # Default: keep string
            return s

        for key, val in list(values_dict.items()):
            values_dict[key] = _convert_value(val)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    def _flatten(d, parent_key=''):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    spec = {}
    # Look for plugin.json first
    json_path = os.path.join(plugin_dir, 'plugin.json')
    yaml_path = os.path.join(plugin_dir, 'plugin.yaml')
    if os.path.isfile(json_path):
        with open(json_path, 'r', encoding='utf-8') as f:
            try:
                spec = json.load(f)
            except json.JSONDecodeError:
                spec = {}
    elif yaml and os.path.isfile(yaml_path):
        with open(yaml_path, 'r', encoding='utf-8') as f:
            try:
                spec = yaml.safe_load(f) or {}
            except Exception:
                spec = {}
    else:
        # No spec file found
        return {}

    if not isinstance(spec, dict):
        return {}

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        config_path = os.path.join(os.path.dirname(__file__), 'config.yaml')
        os.environ['CONFIG_PATH'] = config_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("Root cannot be empty.")
    # Normalize root: remove trailing slashes unless root is just a slash
    if root not in ('/', '\\'):
        root = root.rstrip('/\\')
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    stripped = path[len(root):]
    # Remove leading separator if present
    if stripped.startswith('/') or stripped.startswith('\\'):
        stripped = stripped[1:]
    return stripped
